#!/usr/bin/env bash
set -euo pipefail

# Vendors `px4_msgs` into the ROS 2 tree that get.sh populates.
#
# get.sh fetches prebuilt arm64 debs; px4_msgs has no deb, so it is generated by
# docker/px4-msgs.Dockerfile instead and the artifacts are dropped into the same
# opt/ros/jazzy/{include,lib,share} layout. src/CMakeLists.txt then picks the
# headers up automatically through its `include/*` glob.

DEST="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"                                    # third-party/ros2
REPO="$(cd "$DEST/../.." && pwd)"
ROS="$DEST/opt/ros/jazzy"

PX4_MSGS_REF="${PX4_MSGS_REF:-release/1.15}"                                            # override from the environment to bump the pin

if ! command -v docker >/dev/null 2>&1; then
    echo "ERROR: Docker is not installed or is not available in PATH."
    exit 1
fi

if ! docker info >/dev/null 2>&1; then
    echo "ERROR: Docker is not running."
    exit 1
fi

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

echo ">> building px4_msgs ($PX4_MSGS_REF) for linux/arm64"
docker buildx build \
    --platform linux/arm64 \
    --target export \
    --build-arg "PX4_MSGS_REF=$PX4_MSGS_REF" \
    --file "$REPO/docker/px4-msgs.Dockerfile" \
    --output "type=local,dest=$TMP" \
    "$REPO"

SRC="$TMP/px4_msgs"
[ -d "$SRC/include/px4_msgs" ] || { echo "!! export produced no headers"; exit 1; }

echo ">> vendoring into opt/ros/jazzy"
mkdir -p "$ROS/include" "$ROS/lib" "$ROS/share"

rm -rf "$ROS/include/px4_msgs" "$ROS/share/px4_msgs"
cp -R "$SRC/include/px4_msgs" "$ROS/include/px4_msgs"
cp -R "$SRC/share/px4_msgs"   "$ROS/share/px4_msgs"

# Python bindings are dead weight for a C++-only target, and px4_msgs is ~450
# messages - the tree is already large enough without them.
rm -f "$ROS"/lib/libpx4_msgs__*.so
for so in "$SRC"/lib/libpx4_msgs__*.so; do
    case "$so" in
        *rosidl_generator_py*) continue ;;
    esac
    cp "$so" "$ROS/lib/"
done

echo
echo "Done. px4_msgs $PX4_MSGS_REF vendored:"
echo "  headers : $(find "$ROS/include/px4_msgs" -name '*.hpp' | wc -l | tr -d ' ') files"
echo "  libs    : $(ls "$ROS"/lib/libpx4_msgs__*.so | wc -l | tr -d ' ') files, $(du -sh "$ROS/lib" | cut -f1) total lib dir"
